// JUnit4 test: checks EditDsp.kt against schema/kotlin-dsp/test_vectors.json (generated by the Python engine).
// Copy test_vectors.json to app/src/test/resources/edit/test_vectors.json.
package com.david.aimusicengineer.edit.dsp

import com.david.aimusicengineer.edit.CrossfadeCurve
import com.david.aimusicengineer.edit.EditJson
import com.david.aimusicengineer.edit.LaneItem
import com.david.aimusicengineer.edit.Processor
import com.david.aimusicengineer.edit.Snap
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.boolean
import kotlinx.serialization.json.double
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Test

class EditDspTest {
    private val v: JsonObject = EditJson.parseToJsonElement(
        javaClass.getResource("/edit/test_vectors.json")!!.readText()).jsonObject
    private val tol = v["tolerance"]!!.jsonPrimitive.double
    private fun JsonObject.arr(k: String) = this[k]!!.jsonArray.map { it.jsonPrimitive.double }
    private fun JsonObject.i(k: String) = this[k]!!.jsonPrimitive.int
    private fun near(e: List<Double>, a: List<Double>, what: String) {
        assertEquals("$what length", e.size, a.size)
        e.indices.forEach { assertEquals("$what[$it]", e[it], a[it], tol) }
    }
    private fun curve(s: String) = if (s == "linear") CrossfadeCurve.LINEAR else CrossfadeCurve.EQUAL_POWER

    @Test fun crossfadeCurves() = v["crossfadeCurves"]!!.jsonArray.forEach { c ->
        val o = c.jsonObject; val w = o.arr("w"); val k = curve(o["curve"]!!.jsonPrimitive.content)
        near(o.arr("gainOut"), w.map { CrossfadeMath.gains(it, k).first }, "gainOut")
        near(o.arr("gainIn"), w.map { CrossfadeMath.gains(it, k).second }, "gainIn")
    }

    @Test fun itemsAndLaneComposite() = v["items"]!!.jsonArray.forEach { c ->
        val o = c.jsonObject; val sr = o.i("sampleRate")
        val item = EditJson.decodeFromJsonElement(LaneItem.serializer(), o["item"]!!)
        val g = ItemGeom.of(item, sr); val geo = o["geom"]!!.jsonObject
        assertEquals(geo.i("P"), g.P); assertEquals(geo.i("X"), g.X); assertEquals(geo.i("h"), g.h)
        assertEquals(geo.i("start"), g.start); assertEquals(geo.i("end"), g.end)
        val ts = 0 until 180
        near(o.arr("weight"), ts.map { g.weight(it) }, "weight")
        near(o.arr("envelope"), ts.map { g.envelope(it) }, "envelope")
        val a = o.arr("sourceA").map { it.toFloat() }.toFloatArray()
        val b = o.arr("sourceB").map { it.toFloat() }.toFloatArray()
        val under = LaneItem("a", "A", com.david.aimusicengineer.edit.Range(0, 160), 0,
            crossfade = item.crossfade)
        val geoms = ItemGeom.markSeams(listOf(ItemGeom.of(under, sr), g))
        val out = LaneComposer.compose(geoms, mapOf("A" to StereoSource(a, a), "B" to StereoSource(b, b)), 0, 180)
        near(o.arr("laneOut"), out[0].toList(), "laneOut ${o["mode"]} ${o["curve"]}")
    }

    @Test fun delayEnvelope() = v["delay"]!!.jsonArray.forEach { c ->
        val o = c.jsonObject; val sr = o.i("sampleRate")
        val snap = EditJson.decodeFromJsonElement(Snap.serializer(), o["snap"]!!)
        val p = Processor("d", "delay", params = o["params"]!!.jsonObject,
            fadeInMs = o["fadeInMs"]!!.jsonPrimitive.double, fadeOutMs = o["fadeOutMs"]!!.jsonPrimitive.double)
        val d = DelayProcessor.of(p, sr, snap)
        assertEquals(o.i("delaySamples"), d.delay); assertEquals(o.i("taps"), d.taps); assertEquals(o.i("tail"), d.tail)
        near(o.arr("output"), d.apply(o.arr("input").toDoubleArray(), 0, o.i("spanStart"), o.i("spanEnd")).toList(), "delay")
    }

    @Test fun laneBus() {
        val b = v["laneBus"]!!.jsonObject
        b["gainPan"]!!.jsonArray.forEach { c ->
            val o = c.jsonObject
            val (gl, gr) = LaneBus.gains(o["gainDb"]!!.jsonPrimitive.double, o["pan"]!!.jsonPrimitive.double)
            assertEquals(o["gainL"]!!.jsonPrimitive.double, gl, tol); assertEquals(o["gainR"]!!.jsonPrimitive.double, gr, tol)
            near(o.arr("outL"), o.arr("inL").map { it * gl }, "outL"); near(o.arr("outR"), o.arr("inR").map { it * gr }, "outR")
        }
        b["soloMute"]!!.jsonArray.forEach { c ->
            val lanes = c.jsonObject["lanes"]!!.jsonArray.map { it.jsonObject }
            val got = LaneBus.audibleFlags(lanes.map { it["mute"]!!.jsonPrimitive.boolean }, lanes.map { it["solo"]!!.jsonPrimitive.boolean })
            assertEquals((c.jsonObject["audible"] as JsonArray).map { it.jsonPrimitive.boolean }, got)
        }
    }

    @Test fun softClip() {
        val o = v["softClip"]!!.jsonObject
        near(o.arr("output"), o.arr("input").map { SoftClip.apply(it, o["thresholdDb"]!!.jsonPrimitive.double) }, "softClip")
    }

    @Test fun tempoSync() = v["tempoSync"]!!.jsonArray.forEach { c ->
        val o = c.jsonObject
        val snap = EditJson.decodeFromJsonElement(Snap.serializer(), o["snap"]!!)
        assertEquals(o.i("delaySamples"), TempoSync.delaySamples(o["beats"]!!.jsonPrimitive.double, snap, o.i("sampleRate")))
    }
}
